function goals(){return `<section class="onboarding-screen onboarding-goal-screen">${intro("START WITH THE OUTCOME","What do you want Level Up to help you achieve?","Your answer shapes training emphasis and your starting nutrition strategy.")}<div class="onboarding-goal-grid">${PRIMARY_GOALS.map(([v,l,d])=>`<button class="onboarding-goal-card ${answers.primaryGoal===v?"selected":""}" type="button" data-choice-group="goal" data-choice-value="${v}">${goalIcon(v)}<span><strong>${l}</strong><small>${d}</small></span><i>✓</i></button>`).join("")}</div></section>`}
