function schedule(){return `<section class="onboarding-screen onboarding-schedule-screen">${intro("BUILD AROUND YOUR LIFE","What can you realistically sustain?","Your program will fit your schedule and the equipment you can reliably use.")}<div class="onboarding-week-preview"><div><span>Your training week</span><strong>${answers.days} sessions · ${answers.duration===90?"90+":answers.duration} min</strong></div><div class="onboarding-week-dots" role="group" aria-label="Choose training days">${WEEKDAY_ORDER.map(day=>`<button type="button" class="${answers.trainingDays.includes(day)?"active":""}" data-training-day="${day}" aria-pressed="${answers.trainingDays.includes(day)}" aria-label="${WEEKDAYS[day][1]}">${WEEKDAYS[day][0]}</button>`).join("")}</div><p>Tap the exact days you want to train. These will become your weekly workout schedule.</p></div><h3>Days per week</h3><div class="onboarding-number-row">${[2,3,4,5,6].map(v=>`<button class="onboarding-chip ${answers.days===v?"selected":""}" type="button" data-days="${v}">${v}</button>`).join("")}</div><h3>Typical workout length</h3><div class="onboarding-chip-grid onboarding-duration-grid">${[30,45,60,75,90].map(v=>`<button class="onboarding-chip ${answers.duration===v?"selected":""}" type="button" data-duration="${v}">${v===90?"90+":v}<small>min</small></button>`).join("")}</div><h3>Where do you train?</h3><div class="onboarding-setup-grid">${TRAINING_SETUPS.map(([v,l,d])=>`<button class="onboarding-setup-card ${answers.trainingSetup===v?"selected":""}" type="button" data-training-setup="${v}">${trainingSetupIcon(v)}<strong>${l}</strong><small>${d}</small><i>✓</i></button>`).join("")}</div></section>`}
function trainingSetupIcon(value){const paths={full_gym:'<path d="M4 21V5h16v16M8 9h2m4 0h2M8 13h2m4 0h2M8 17h2m4 0h2M10 21v-4h4v4M2 21h20"/>',home_gym:'<path d="M3 11 12 3l9 8v10H3ZM8 15v4m8-4v4M6 17h12M7 15v4m10-4v4"/>',minimal:'<path d="M3 9v6m3-8v10m12-10v10m3-8v6M6 12h12"/>',bodyweight:'<circle cx="12" cy="5" r="2.5"/><path d="M12 8v6m0-3-5 3m5-3 5 3m-5 0-4 7m4-7 4 7"/>'};return `<span class="onboarding-setup-icon" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[value]}</svg></span>`}
