function preferences(){return `<section class="onboarding-screen onboarding-preference-screen">${intro("TRAIN YOUR WAY","Anything you would prefer to avoid?","Level Up can swap exercises while preserving the purpose of your program.")}<div class="onboarding-swap-preview"><span><small>PROGRAMMED</small><strong>Barbell squat</strong></span><i>→</i><span><small>SMART SWAP</small><strong>Leg press</strong></span></div><div class="onboarding-option-stack onboarding-limit-options">${choice("limitations","none","No preferences or limitations",answers.limitationMode==="none","Use the best-matched exercises.")}${choice("limitations","choose","Choose exercises to avoid",answers.limitationMode==="choose","Search your exercise library.")}</div>${answers.limitationMode==="choose"?`<div class="onboarding-exercise-picker"><input id="onboarding-exercise-search" type="search" value="${esc(answers.exerciseSearch)}" placeholder="Search exercise, muscle or equipment"><div class="onboarding-selected-exercises">${selectedExercises()}</div><div id="onboarding-exercise-results" class="onboarding-exercise-results"></div></div>`:""}<p class="onboarding-safety-note">Exercise preferences are not a medical screening. Stop if an exercise causes pain.</p></section>`}
