function nutritionActivity(){return `<section class="onboarding-screen">${intro("ENERGY NEEDS","How active is your typical week?","This helps Level Up estimate your maintenance calories.")}<div class="onboarding-option-stack">${Object.entries(ACTIVITY_LEVELS).map(([id,item])=>`<button class="onboarding-option ${answers.nutritionActivity===id?"selected":""}" type="button" data-nutrition-activity="${esc(id)}"><strong>${esc(item.label)}</strong><small>${esc(item.description)}</small><i>✓</i></button>`).join("")}</div></section>`}
