function nutritionPreview(){const profile=nutritionProfileFromAnswers(),goal=GOAL_PRESETS[answers.nutritionGoalId];if(!profile||!ACTIVITY_LEVELS[answers.nutritionActivity]||!goal)return null;try{const maintenance=Math.round(Number(calculateTdee({...profile,activity:answers.nutritionActivity}).tdee));if(!Number.isFinite(maintenance)||maintenance<=0)return null;return{maintenance,adjustment:Number(goal.dailyCalorieAdjustment||0),target:Math.round(maintenance+Number(goal.dailyCalorieAdjustment||0))}}catch{return null}}
function nutritionPreviewMarkup(plan){const sign=plan.adjustment>0?"+":plan.adjustment<0?"−":"",absolute=Math.abs(plan.adjustment),equation=plan.adjustment===0?`${plan.maintenance.toLocaleString()} maintenance = ${plan.target.toLocaleString()} target`:`${plan.maintenance.toLocaleString()} ${sign} ${absolute.toLocaleString()} = ${plan.target.toLocaleString()} target`;return `<div class="onboarding-nutrition-preview"><div><span>Estimated maintenance</span><strong>${plan.maintenance.toLocaleString()} kcal/day</strong></div><div><span>Goal adjustment</span><strong>${sign}${absolute.toLocaleString()} kcal/day</strong></div><div><span>Starting calorie target</span><strong>${plan.target.toLocaleString()} kcal/day</strong></div><p class="onboarding-nutrition-equation"><strong>${equation}</strong><span>Maintenance is the starting point used to calculate your target.</span></p></div>`}
