 if(answers.nutritionMode==="manual"){localStorage.setItem(MANUAL_TARGET_KEY,String(plan.target));setMaintenanceUpdateMode("track")}else setMaintenanceUpdateMode(answers.coachUpdateMode==="automatic"?"automatic":"review");
