function suggestNutritionGoal(goal){if(goal==="build_muscle")return"bulk_conservative";if(goal==="lose_fat_maintain_muscle")return"cut_gentle";if(goal==="maintain_muscle")return"maintain";return""}
function saveInitialWeight(weight){const entries=readJson(WEIGHT_KEY);if(Array.isArray(entries)&&entries.length)return;const n=new Date(),date=`${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")}`;localStorage.setItem(WEIGHT_KEY,JSON.stringify([{date,weight:Math.round(Number(weight)*10)/10}]))}
