function renderExerciseResults(){const host=overlay?.querySelector("#onboarding-exercise-results");if(!host)return;const q=String(answers.exerciseSearch||"").trim().toLowerCase(),selected=new Set(answers.excludedIds),results=getAllExercises().filter(x=>x.trackingType!=="notes"&&!selected.has(x.id)).filter(x=>!q||[x.name,x.muscleGroup,x.equipment].some(v=>String(v||"").toLowerCase().includes(q))).sort((a,b)=>String(a.muscleGroup).localeCompare(String(b.muscleGroup))||String(a.name).localeCompare(String(b.name))).slice(0,12);host.innerHTML=results.length?results.map(x=>`<button class="onboarding-exercise-row" type="button" data-avoid-add="${esc(x.id)}"><span><strong>${esc(x.name)}</strong><small>${esc(x.muscleGroup)} · ${esc(x.equipment)}</small></span><b>Avoid</b></button>`).join(""):'<p class="onboarding-helper">No matching exercises.</p>'}
